    "contracts/strategies/polygon/interfaces/univ3/IUniswapV3Staker.sol": {
      "content": "// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity ^0.8.0;
pragma experimental ABIEncoderV2;

import "./IUniswapV3Pool.sol";

interface IERC20Minimal {
  /// @notice Returns the balance of a token
  /// @param account The account for which to look up the number of tokens it has, i.e. its balance
  /// @return The number of tokens held by the account
  function balanceOf(address account) external view returns (uint256);

  /// @notice Transfers the amount of token from the `msg.sender` to the recipient
  /// @param recipient The account that will receive the amount transferred
  /// @param amount The number of tokens to send from the sender to the recipient
  /// @return Returns true for a successful transfer, false for an unsuccessful transfer
  function transfer(address recipient, uint256 amount) external returns (bool);

  /// @notice Returns the current allowance given to a spender by an owner
  /// @param owner The account of the token owner
  /// @param spender The account of the token spender
  /// @return The current allowance granted by `owner` to `spender`
  function allowance(address owner, address spender) external view returns (uint256);

  /// @notice Sets the allowance of a spender from the `msg.sender` to the value `amount`
  /// @param spender The account which will be allowed to spend a given amount of the owners tokens
  /// @param amount The amount of tokens allowed to be used by `spender`
  /// @return Returns true for a successful approval, false for unsuccessful
  function approve(address spender, uint256 amount) external returns (bool);

  /// @notice Transfers `amount` tokens from `sender` to `recipient` up to the allowance given to the `msg.sender`
  /// @param sender The account from which the transfer will be initiated
  /// @param recipient The recipient of the transfer
  /// @param amount The amount of the transfer
  /// @return Returns true for a successful transfer, false for unsuccessful
  function transferFrom(
    address sender,
    address recipient,
    uint256 amount
  ) external returns (bool);

  /// @notice Event emitted when tokens are transferred from one address to another, either via `#transfer` or `#transferFrom`.
  /// @param from The account from which the tokens were sent, i.e. the balance decreased
  /// @param to The account to which the tokens were sent, i.e. the balance increased
  /// @param value The amount of tokens that were transferred
  event Transfer(address indexed from, address indexed to, uint256 value);

  /// @notice Event emitted when the approval amount for the spender of a given owner's tokens changes.
  /// @param owner The account that approved spending of its tokens
  /// @param spender The account for which the spending allowance was modified
  /// @param value The new allowance from the owner to the spender
  event Approval(address indexed owner, address indexed spender, uint256 value);
}

/// @title Uniswap V3 Staker Interface
/// @notice Allows staking nonfungible liquidity tokens in exchange for reward tokens
interface IUniswapV3Staker {
  /// @param rewardToken The token being distributed as a reward
  /// @param pool The Uniswap V3 pool
  /// @param startTime The time when the incentive program begins
  /// @param endTime The time when rewards stop accruing
  /// @param refundee The address which receives any remaining reward tokens when the incentive is ended
  struct IncentiveKey {
    IERC20Minimal rewardToken;
    IUniswapV3Pool pool;
    uint256 startTime;
    uint256 endTime;
    address refundee;
  }

  /// @notice The max duration of an incentive in seconds
  function maxIncentiveDuration() external view returns (uint256);

  /// @notice The max amount of seconds into the future the incentive startTime can be set
  function maxIncentiveStartLeadTime() external view returns (uint256);

  /// @notice Represents a staking incentive
  /// @param incentiveId The ID of the incentive computed from its parameters
  /// @return totalRewardUnclaimed The amount of reward token not yet claimed by users
  /// @return totalSecondsClaimedX128 Total liquidity-seconds claimed, represented as a UQ32.128
  /// @return numberOfStakes The count of deposits that are currently staked for the incentive
  function incentives(bytes32 incentiveId)
    external
    view
    returns (
      uint256 totalRewardUnclaimed,
      uint160 totalSecondsClaimedX128,
      uint96 numberOfStakes
    );

  /// @notice Returns information about a deposited NFT
  /// @return owner The owner of the deposited NFT
  /// @return numberOfStakes Counter of how many incentives for which the liquidity is staked
  /// @return tickLower The lower tick of the range
  /// @return tickUpper The upper tick of the range
  function deposits(uint256 tokenId)
    external
    view
    returns (
      address owner,
      uint48 numberOfStakes,
      int24 tickLower,
      int24 tickUpper
    );

  /// @notice Returns information about a staked liquidity NFT
  /// @param tokenId The ID of the staked token
  /// @param incentiveId The ID of the incentive for which the token is staked
  /// @return secondsPerLiquidityInsideInitialX128 secondsPerLiquidity represented as a UQ32.128
  /// @return liquidity The amount of liquidity in the NFT as of the last time the rewards were computed
  function stakes(uint256 tokenId, bytes32 incentiveId)
    external
    view
    returns (uint160 secondsPerLiquidityInsideInitialX128, uint128 liquidity);

  /// @notice Returns amounts of reward tokens owed to a given address according to the last time all stakes were updated
  /// @param rewardToken The token for which to check rewards
  /// @param owner The owner for which the rewards owed are checked
  /// @return rewardsOwed The amount of the reward token claimable by the owner
  function rewards(IERC20Minimal rewardToken, address owner) external view returns (uint256 rewardsOwed);

  /// @notice Creates a new liquidity mining incentive program
  /// @param key Details of the incentive to create
  /// @param reward The amount of reward tokens to be distributed
  function createIncentive(IncentiveKey memory key, uint256 reward) external;

  /// @notice Ends an incentive after the incentive end time has passed and all stakes have been withdrawn
  /// @param key Details of the incentive to end
  /// @return refund The remaining reward tokens when the incentive is ended
  function endIncentive(IncentiveKey memory key) external returns (uint256 refund);

  /// @notice Transfers ownership of a deposit from the sender to the given recipient
  /// @param tokenId The ID of the token (and the deposit) to transfer
  /// @param to The new owner of the deposit
  function transferDeposit(uint256 tokenId, address to) external;

  /// @notice Withdraws a Uniswap V3 LP token `tokenId` from this contract to the recipient `to`
  /// @param tokenId The unique identifier of an Uniswap V3 LP token
  /// @param to The address where the LP token will be sent
  /// @param data An optional data array that will be passed along to the `to` address via the NFT safeTransferFrom
  function withdrawToken(
    uint256 tokenId,
    address to,
    bytes memory data
  ) external;

  /// @notice Stakes a Uniswap V3 LP token
  /// @param key The key of the incentive for which to stake the NFT
  /// @param tokenId The ID of the token to stake
  function stakeToken(IncentiveKey memory key, uint256 tokenId) external;

  /// @notice Unstakes a Uniswap V3 LP token
  /// @param key The key of the incentive for which to unstake the NFT
  /// @param tokenId The ID of the token to unstake
  function unstakeToken(IncentiveKey memory key, uint256 tokenId) external;

  /// @notice Transfers `amountRequested` of accrued `rewardToken` rewards from the contract to the recipient `to`
  /// @param rewardToken The token being distributed as a reward
  /// @param to The address where claimed rewards will be sent to
  /// @param amountRequested The amount of reward tokens to claim. Claims entire reward amount if set to 0.
  /// @return reward The amount of reward tokens claimed
  function claimReward(
    IERC20Minimal rewardToken,
    address to,
    uint256 amountRequested
  ) external returns (uint256 reward);

  /// @notice Calculates the reward amount that will be received for the given stake
  /// @param key The key of the incentive
  /// @param tokenId The ID of the token
  /// @return reward The reward accrued to the NFT for the given incentive thus far
  function getRewardInfo(IncentiveKey memory key, uint256 tokenId)
    external
    returns (uint256 reward, uint160 secondsInsideX128);

  /// @notice Event emitted when a liquidity mining incentive has been created
  /// @param rewardToken The token being distributed as a reward
  /// @param pool The Uniswap V3 pool
  /// @param startTime The time when the incentive program begins
  /// @param endTime The time when rewards stop accruing
  /// @param refundee The address which receives any remaining reward tokens after the end time
  /// @param reward The amount of reward tokens to be distributed
  event IncentiveCreated(
    IERC20Minimal indexed rewardToken,
    IUniswapV3Pool indexed pool,
    uint256 startTime,
    uint256 endTime,
    address refundee,
    uint256 reward
  );

  /// @notice Event that can be emitted when a liquidity mining incentive has ended
  /// @param incentiveId The incentive which is ending
  /// @param refund The amount of reward tokens refunded
  event IncentiveEnded(bytes32 indexed incentiveId, uint256 refund);

  /// @notice Emitted when ownership of a deposit changes
  /// @param tokenId The ID of the deposit (and token) that is being transferred
  /// @param oldOwner The owner before the deposit was transferred
  /// @param newOwner The owner after the deposit was transferred
  event DepositTransferred(uint256 indexed tokenId, address indexed oldOwner, address indexed newOwner);

  /// @notice Event emitted when a Uniswap V3 LP token has been staked
  /// @param tokenId The unique identifier of an Uniswap V3 LP token
  /// @param liquidity The amount of liquidity staked
  /// @param incentiveId The incentive in which the token is staking
  event TokenStaked(uint256 indexed tokenId, bytes32 indexed incentiveId, uint128 liquidity);

  /// @notice Event emitted when a Uniswap V3 LP token has been unstaked
  /// @param tokenId The unique identifier of an Uniswap V3 LP token
  /// @param incentiveId The incentive in which the token is staking
  event TokenUnstaked(uint256 indexed tokenId, bytes32 indexed incentiveId);

  /// @notice Event emitted when a reward token has been claimed
  /// @param to The address where claimed rewards were sent to
  /// @param reward The amount of reward tokens claimed
  event RewardClaimed(address indexed to, uint256 reward);
}
"
    },
    "contracts/strategies/polygon/interfaces/univ3/pool/IUniswapV3PoolActions.sol": {
      "content": "// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Permissionless pool actions
/// @notice Contains pool methods that can be called by anyone
interface IUniswapV3PoolActions {
    /// @notice Adds liquidity for the given recipient/tickLower/tickUpper position
    /// @dev The caller of this method receives a callback in the form of IUniswapV3MintCallback#uniswapV3MintCallback
    /// in which they must pay any token0 or token1 owed for the liquidity. The amount of token0/token1 due depends
    /// on tickLower, tickUpper, the amount of liquidity, and the current price.
    /// @param recipient The address for which the liquidity will be created
    /// @param tickLower The lower tick of the position in which to add liquidity
    /// @param tickUpper The upper tick of the position in which to add liquidity
    /// @param amount The amount of liquidity to mint
    /// @param data Any data that should be passed through to the callback
    /// @return amount0 The amount of token0 that was paid to mint the given amount of liquidity. Matches the value in the callback
    /// @return amount1 The amount of token1 that was paid to mint the given amount of liquidity. Matches the value in the callback
    function mint(
        address recipient,
        int24 tickLower,
        int24 tickUpper,
        uint128 amount,
        bytes calldata data
    ) external returns (uint256 amount0, uint256 amount1);

    /// @notice Collects tokens owed to a position
    /// @dev Does not recompute fees earned, which must be done either via mint or burn of any amount of liquidity.
    /// Collect must be called by the position owner. To withdraw only token0 or only token1, amount0Requested or
    /// amount1Requested may be set to zero. To withdraw all tokens owed, caller may pass any value greater than the
    /// actual tokens owed, e.g. type(uint128).max. Tokens owed may be from accumulated swap fees or burned liquidity.
    /// @param recipient The address which should receive the fees collected
    /// @param tickLower The lower tick of the position for which to collect fees
    /// @param tickUpper The upper tick of the position for which to collect fees
    /// @param amount0Requested How much token0 should be withdrawn from the fees owed
    /// @param amount1Requested How much token1 should be withdrawn from the fees owed
    /// @return amount0 The amount of fees collected in token0
    /// @return amount1 The amount of fees collected in token1
    function collect(
        address recipient,
        int24 tickLower,
        int24 tickUpper,
        uint128 amount0Requested,
        uint128 amount1Requested
    ) external returns (uint128 amount0, uint128 amount1);

    /// @notice Burn liquidity from the sender and account tokens owed for the liquidity to the position
    /// @dev Can be used to trigger a recalculation of fees owed to a position by calling with an amount of 0
    /// @dev Fees must be collected separately via a call to #collect
    /// @param tickLower The lower tick of the position for which to burn liquidity
    /// @param tickUpper The upper tick of the position for which to burn liquidity
    /// @param amount How much liquidity to burn
    /// @return amount0 The amount of token0 sent to the recipient
    /// @return amount1 The amount of token1 sent to the recipient
    function burn(
        int24 tickLower,
        int24 tickUpper,
        uint128 amount
    ) external returns (uint256 amount0, uint256 amount1);

    /// @notice Swap token0 for token1, or token1 for token0
    /// @dev The caller of this method receives a callback in the form of IUniswapV3SwapCallback#uniswapV3SwapCallback
    /// @param recipient The address to receive the output of the swap
    /// @param zeroForOne The direction of the swap, true for token0 to token1, false for token1 to token0
    /// @param amountSpecified The amount of the swap, which implicitly configures the swap as exact input (positive), or exact output (negative)
    /// @param sqrtPriceLimitX96 The Q64.96 sqrt price limit. If zero for one, the price cannot be less than this
    /// value after the swap. If one for zero, the price cannot be greater than this value after the swap
    /// @param data Any data to be passed through to the callback
    /// @return amount0 The delta of the balance of token0 of the pool, exact when negative, minimum when positive
    /// @return amount1 The delta of the balance of token1 of the pool, exact when negative, minimum when positive
    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}
"
    },
    "contracts/strategies/polygon/interfaces/univ3/pool/IUniswapV3PoolDerivedState.sol": {
      "content": "// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Pool state that is not stored
/// @notice Contains view functions to provide information about the pool that is computed rather than stored on the
/// blockchain. The functions here may have variable gas costs.
interface IUniswapV3PoolDerivedState {
    /// @notice Returns the cumulative tick and liquidity as of each timestamp `secondsAgo` from the current block timestamp
    /// @dev To get a time weighted average tick or liquidity-in-range, you must call this with two values, one representing
    /// the beginning of the period and another for the end of the period. E.g., to get the last hour time-weighted average tick,
    /// you must call it with secondsAgos = [3600, 0].
    /// @dev The time weighted average tick represents the geometric time weighted average price of the pool, in
    /// log base sqrt(1.0001) of token1 / token0. The TickMath library can be used to go from a tick value to a ratio.
    /// @param secondsAgos From how long ago each cumulative tick and liquidity value should be returned
    /// @return tickCumulatives Cumulative tick values as of each `secondsAgos` from the current block timestamp
    /// @return secondsPerLiquidityCumulativeX128s Cumulative seconds per liquidity-in-range value as of each `secondsAgos` from the current block
    /// timestamp
    function observe(uint32[] calldata secondsAgos)
        external
        view
        returns (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s);
}
"
    },
    "contracts/strategies/polygon/interfaces/univ3/pool/IUniswapV3PoolImmutables.sol": {
      "content": "// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Pool state that never changes
/// @notice These parameters are fixed for a pool forever, i.e., the methods will always return the same values
interface IUniswapV3PoolImmutables {
    /// @notice The first of the two tokens of the pool, sorted by address
    /// @return The token contract address
    function token0() external view returns (address);

    /// @notice The second of the two tokens of the pool, sorted by address
    /// @return The token contract address
    function token1() external view returns (address);

    /// @notice The pool tick spacing
    /// @dev Ticks can only be used at multiples of this value, minimum of 1 and always positive
    /// e.g.: a tickSpacing of 3 means ticks can be initialized every 3rd tick, i.e., ..., -6, -3, 0, 3, 6, ...
    /// This value is an int24 to avoid casting even though it is always positive.
    /// @return The tick spacing
    function tickSpacing() external view returns (int24);
}
"
    },
    "contracts/strategies/polygon/interfaces/univ3/pool/IUniswapV3PoolState.sol": {
      "content": "// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Pool state that can change
/// @notice These methods compose the pool's state, and can change with any frequency including multiple times
/// per transaction
interface IUniswapV3PoolState {
    /// @notice The 0th storage slot in the pool stores many values, and is exposed as a single method to save gas
    /// when accessed externally.
    /// @return sqrtPriceX96 The current price of the pool as a sqrt(token1/token0) Q64.96 value
    /// tick The current tick of the pool, i.e. according to the last tick transition that was run.
    /// This value may not always be equal to SqrtTickMath.getTickAtSqrtRatio(sqrtPriceX96) if the price is on a tick
    /// boundary.
    /// observationIndex The index of the last oracle observation that was written,
    /// observationCardinality The current maximum number of observations stored in the pool,
    /// observationCardinalityNext The next maximum number of observations, to be updated when the observation.
    /// feeProtocol The protocol fee for both tokens of the pool.
    /// Encoded as two 4 bit values, where the protocol fee of token1 is shifted 4 bits and the protocol fee of token0
    /// is the lower 4 bits. Used as the denominator of a fraction of the swap fee, e.g. 4 means 1/4th of the swap fee.
    /// unlocked Whether the pool is currently locked to reentrancy
    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96,
            int24 tick,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        );

    /// @notice Returns the information about a position by the position's key
    /// @param key The position's key is a hash of a preimage composed by the owner, tickLower and tickUpper
    /// @return _liquidity The amount of liquidity in the position,
    /// Returns feeGrowthInside0LastX128 fee growth of token0 inside the tick range as of the last mint/burn/poke,
    /// Returns feeGrowthInside1LastX128 fee growth of token1 inside the tick range as of the last mint/burn/poke,
    /// Returns tokensOwed0 the computed amount of token0 owed to the position as of the last mint/burn/poke,
    /// Returns tokensOwed1 the computed amount of token1 owed to the position as of the last mint/burn/poke
    function positions(bytes32 key)
        external
        view
        returns (
            uint128 _liquidity,
            uint256 feeGrowthInside0LastX128,
            uint256 feeGrowthInside1LastX128,
            uint128 tokensOwed0,
            uint128 tokensOwed1
        );
}
"
    },
    "contracts/strategies/polygon/quickswap/interfaces/IControllerV7.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
pragma experimental ABIEncoderV2;

interface IControllerV7 {
  enum Governance {
    devfund,
    treasury,
    strategist,
    governance,
    timelock
  }

  enum Strategy {
    vault,
    revoke,
    approve,
    removeVault,
    removeStrategy,
    setStrategy
  }

  enum Withdraw {
    withdrawAll,
    inCaseTokensGetStuck,
    inCaseStrategyTokenGetStuck,
    withdraw,
    withdrawReward
  }

  function converters(address, address) external view returns (address);

  function earn(
    address _pool,
    uint256 _token0Amount,
    uint256 _token1Amount
  ) external;

  function getLowerTick(address _pool) external view returns (int24);

  function getUpperTick(address _pool) external view returns (int24);

  function governance(uint8) external view returns (address);

  function liquidityOf(address _pool) external view returns (uint256);

  function onERC721Received(
    address,
    address,
    uint256,
    bytes memory
  ) external pure returns (bytes4);

  function strategies(address) external view returns (address);

  function treasury() external view returns (address);

  function vaults(address) external view returns (address);

  function withdraw(address _pool, uint256 _amount) external returns (uint256 a0, uint256 a1);

  function withdrawFunction(
    uint8 name,
    address _pool,
    uint256 _amount,
    address _token
  ) external returns (uint256, uint256);
}
"
